INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p943263-ee445', 'stk-ieee', 'EE 445', 'info', '{"desc": "السلام عليكم…\n\nما هو الفرق بين السيارة والطيارة؟ أو ما هو الفرق بين كبسة لحم وكبسة دجاج؟\nهذا ما يحاول أغلبنا طرحه بهذا الأسلوب. فشتان بين كل منهما.\nوالحقيقة فليس هناك مادة أفضل من أخرى أو أهم منها، وليست دائما نظرية أن سوق العمل هو الذي يحدد حياتك واختياراتك العلمية أثناء الدراسة. فالمهندس الكهربائي الناجح والمتمكن يستطيع التنقل بين التخصصات “من طاقة لتحكم او من اتصالات لإلكترونيات” فالمسألة مجرد تدريب وقراءة وممارسة لا أكثر. فبالتالي قضية أن أحصر نفسي لأجل عيون الشركة س والشركة ص والشركة ع وأقنن خياراتي الدراسية على حسب ما يتطلبونه هم فهو أمر بعيد عن الواقعية. والسبب ببساطة ان الشركة الناجحة ستعمل على تدريب المهندس المبتدئ على سياساتها وطريقة عملها من الصفر فلن تعتمد بشكل كبير على موادك إلا الأساسيات منها والتي سبق وأن أخذتها في مواد السفمور والجونيور. نحن لانقول هنا أن أخذ مادة يتطلبها سوق العمل أمر خاطئ بل الأفضل أن تختار ما يحقق التالي:\n\nالتخصص والإبداع فيه يعتمد على مدى راحتك للمادة بشكل كبير ومدى تعلقك بها وهو أمر شخصي بحت. اختر ما يروق لك أنت وليس ما يروق للآخرين. فهو كمسألة الزواج، فمن غير المنطقي ان تختار ما يريده فلان ، بل ما تريده انت فقط.\nطرح المادة وطريقة شرحها والاستفادة منها يعتمد بشكل رئيس على المدرس. فقد يكون هناك مفاضلة بين مادتين مميزتين إلا أن إحداها يدرسها شخص غير مبال بالطلاب فابتعد عنه.\nاختيار المادة ليس له علاقة بضمان الحصول على c أو b أو a من المدرس، فدع عنك ترهات السنوات الأولى من الجامعة التي تجعل طموحك الدرجة بغض النظر عن المادة وفهمها. وثق تماما أن فهمك وإبداعك سيصل بك لما تطمح إليه.\nحاول التركيز على المواد التي تنمي تفكيرك كمهندس وليس كآلة حاسبة تقوم بحل مسائل رياضية. فالمادة التي تحتاج إلى شخص يتقن حل المسائل الرياضية لن تجعلك مهندسا بل مجرد طالب رياضيات. فالمواد التي بها تفكير هندسي وحل لمشاكل واقعية وتصاميم هي الهدف الأسمى.\nليس هناك مادة تلبي كافة طموحاتك، فلابد من التضحية إما على حساب الوقت أو الجهد أو التعارض مع مواد أخرى أو غيرها. فلا تحدك الظروف للتضحية بالعلم.\nليس هناك مانع من ان تحضر أي مادة كمستمع، فهو نظام مميز في جامعتنا يتيح لك أن تحضر أي مادة دون دخول اختباراتها وستسجل لك في سجلك الأكاديمي. فاحرص على الاستفادة من هذه النقطة في سبيل زيادة حصيلتك العلمية.\nسوق العمل بحاجة لمهندسين من كافة التخصصات ونسبة الحاجة لتخصص معين تختلف حسب نوعية المشاريع التي في السوق حاليا، فلاتربط نفسك بمسألة مشروع معين. بل فكر في المستقبل.\nانتقل الآن لمادة ee445 كوني درستها لدى العالم محمد أبو المعاطي، فإذا كان هو من يدرسها فخذها بلا تردد، فستتعلم من خلالها طريقة التفكير كمهندس محترف يحل مشاكل هندسية حقيقية وليس مسائل رياضية فقط. خلال المادة ستتعرف إلى التطبيقات الصناعية للإلكترونيات ودارات عملية تشاهدها من حولك.\nمواد الطاقة بشكل عام تبقى أسهل نظريا من مواد التخصصات الأخرى فاحرص أن تفهم الأصعب.\n\nحظا موفقا لكم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee445-industrial-electronics/102213/10", "user": "ieee", "ts": 1323149612000, "tid": 102213, "pn": 10}}', 1323149612000, 1794826858, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
